<script setup lang="ts">
import {ref,onMounted,onUnmounted,computed} from 'vue';
import {request,post} from '../api';
import StockSearch,{type SearchStock} from './StockSearch.vue';
import RiskCalculator from './RiskCalculator.vue';
type Technical={date:string;close:number;observed_at:string;ma5:number;ma20:number;atr14:number;support10:number;resistance20:number;volume_ratio:number|null;source:string;conditional_levels?:{entry:number;stop:number}};
type Plan={entry:number;entry_upper:number;stop:number;target_2r:number;target_3r:number;trailing_stop_distance:number;entry_condition:string;invalidation:string;status:string;position:string;horizon:string};
type Report={instrument_id:string;name:string;code:string;days:number;as_of:string;version:string;method:string;score:number|null;coverage:number;status:string;risk_level:string;vetoes:string[];price_reasons:string[];technical:Technical|null;plan:Plan|null;record_id?:number;
  components:{key:string;label:string;weight:number;score:number|null;covered_weight:number;reason:string}[];scenarios:{name:string;condition:string;action:string}[];limitations:string[];
  sample:{effective_posts:number;authors:number;counts:Record<string,number>;observed_at:string|null};evidence:{source_id:string;excerpt:string;url:string;label:string}[]};
type Entry={id:number;created_at:string;version:string;result:Report};
const props=defineProps<{initialInstrument:string;holdings?:boolean}>();
const emit=defineEmits<{select:[id:string]}>();
const iid=ref(props.initialInstrument),days=ref(3),data=ref<Report|null>(null),busy=ref(false),error=ref(''),notice=ref(''),records=ref<Entry[]>([]),historical=ref(false);
let version=0,disposed=false;
const title=computed(()=>props.holdings?'持仓管理':'智能交易决策中心');
const time=(s:string)=>new Date(s).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',hour12:false});
const num=(n:number|null|undefined)=>n===null||n===undefined?'—':n.toFixed(2);
const states=[['强势机会','等待合适入场条件'],['观察机会','等待突破或回踩确认'],['持仓跟踪','核验可卖数量及移动止盈'],['风险预警','核对风险预算与持仓'],['回避观望','等待风险解除']];
async function load(){const current=++version;data.value=null;error.value='';historical.value=false;try{const [result,history]=await Promise.all([request<Report>(`/live/decision?${new URLSearchParams({instrument_id:iid.value,days:String(days.value)})}`),request<Entry[]>(`/live/decision/history?instrument_id=${encodeURIComponent(iid.value)}`)]);if(!disposed&&current===version){data.value=result;records.value=history;}}catch(e){if(!disposed)error.value=e instanceof Error?e.message:'决策数据读取失败';}}
async function choose(s:SearchStock){iid.value=s.id;emit('select',s.id);notice.value='';await load();}
async function generate(){if(busy.value)return;++version;busy.value=true;error.value='';notice.value='';historical.value=false;try{const observed=await request<{collection:{message:string}}>('/live/analyze',{method:'POST',body:JSON.stringify({instrument_id:iid.value,days:days.value,content:'titles',limit:3})},150000);if(disposed)return;notice.value=observed.collection.message;data.value=await post<Report>('/live/decision',{instrument_id:iid.value,days:days.value});records.value=await request<Entry[]>(`/live/decision/history?instrument_id=${encodeURIComponent(iid.value)}`);}catch(e){if(!disposed)error.value=e instanceof Error?e.message:'生成失败';}finally{if(!disposed)busy.value=false;}}
function openRecord(entry:Entry){data.value=entry.result;historical.value=true;notice.value=`正在查看历史方案 #${entry.id}，数据截止 ${time(entry.result.as_of)}；不作为当前参考价。`;}
onMounted(load);onUnmounted(()=>{disposed=true;++version;});
</script>
<template>
  <div class="decision-center">
    <section class="panel decision-search"><div class="decision-heading"><div><h1>{{title}}</h1><p class="subtle">{{holdings?'输入已有持仓，计算盈亏、可卖数量和账户风险':'真实数据 → 六维核验 → 条件式方案 → 风险预算'}}</p></div><span class="subtle">规则引擎 · v1</span></div><StockSearch :disabled="busy" @select="choose"/><div class="decision-selector"><strong>{{data?.name||iid}} <small>{{iid}}</small></strong><label>统计窗口<select v-model="days" :disabled="busy" @change="load"><option v-for="n in [1,3,5,10,20]" :key="n" :value="n">{{n===1?'今日':`近${n}自然日`}}</option></select></label><button class="primary" :disabled="busy" @click="generate">{{busy?'正在核验数据…':'更新数据并生成方案'}}</button></div></section>
    <p v-if="error" class="error-banner" role="alert">{{error}}</p><p v-if="notice" class="decision-notice" role="status">{{notice}}</p>
    <template v-if="data">
      <section class="panel decision-summary"><div><span>综合决策评分</span><strong>{{data.score??'—'}}<small> / 100</small></strong><p class="subtle">六维权重覆盖 {{data.coverage}}%</p></div><div><span>当前操作状态</span><h2>{{data.status}}</h2><p class="subtle">{{data.risk_level}}</p></div><div class="decision-asof"><span>{{historical?'历史方案截止':'数据截止'}}</span><p>{{time(data.as_of)}}</p><small>{{data.version}}{{data.record_id?` · 方案 #${data.record_id}`:''}}</small></div></section>
      <section class="panel decision-gates"><h2>执行条件核验</h2><ul><li v-for="reason in data.vetoes" :key="reason">{{reason}}</li></ul><p class="subtle">当前不输出直接买入、加仓或做空指令。以下技术位与仓位计算为可核对的条件参考。</p></section>
      <RiskCalculator v-if="holdings" :instrument-id="iid" :reference-price="!historical&&!data.price_reasons.length?data.technical?.close:null" :entry="!historical?data.plan?.entry:null" :stop="!historical?data.plan?.stop:null" holdings/>
      <section class="panel"><h2>六维决策依据</h2><div class="decision-dimensions"><article v-for="c in data.components" :key="c.key"><header><h3>{{c.label}}</h3><span>{{c.weight}}%</span></header><strong>{{c.score===null?'待数据':c.score.toFixed(1)}}</strong><div class="dimension-track"><i :style="{width:(c.score??0)+'%'}"/></div><p>{{c.reason}}</p></article></div></section>
      <section class="panel technical-reference"><div class="panel-heading"><h2>真实行情与技术参考</h2><span class="subtle">{{data.technical?.source||'尚未保存行情'}}</span></div><template v-if="data.technical"><div class="technical-grid"><div v-for="[label,value] in [['完整日线收盘',data.technical.close],['MA5',data.technical.ma5],['MA20',data.technical.ma20],['ATR14',data.technical.atr14],['10日低点',data.technical.support10],['前20日高点',data.technical.resistance20],['成交量/前20日均量',data.technical.volume_ratio]]" :key="String(label)"><span>{{label}}</span><strong>{{num(value as number|null)}}</strong></div></div><p class="subtle">日线 {{data.technical.date}} · 观察 {{time(data.technical.observed_at)}} · 未复权，非实时成交价</p></template><p v-else class="decision-empty">没有足够完整日线，暂不生成价位。</p><p v-if="data.price_reasons.length" class="decision-risk">{{data.price_reasons.join('；')}}</p></section>
      <section class="panel conditional-plan"><div class="panel-heading"><h2>个股条件式操作方案</h2><span class="subtle">{{data.plan?.horizon||'未来3～5个交易日 · 等待数据'}}</span></div><template v-if="data.plan"><p class="decision-risk">{{data.plan.status}}</p><div class="plan-grid"><div><span>突破观察区间</span><strong>{{num(data.plan.entry)}} — {{num(data.plan.entry_upper)}}</strong></div><div><span>结构止损参考</span><strong>{{num(data.plan.stop)}}</strong></div><div><span>2R / 3R研究价位</span><strong>{{num(data.plan.target_2r)}} / {{num(data.plan.target_3r)}}</strong></div><div><span>移动止盈参考距离</span><strong>{{num(data.plan.trailing_stop_distance)}} 元</strong></div></div><p>{{data.plan.entry_condition}}</p><p class="subtle">{{data.plan.invalidation}}。2R/3R是风险倍数计算结果，不是目标价预测。</p></template><p v-else class="decision-empty">样本或行情未通过门槛，暂不生成买卖价位。可查看技术数据、补充样本，并用下方计算器验证你自行设定的方案。</p></section>
      <RiskCalculator v-if="!holdings" :instrument-id="iid" :reference-price="!historical&&!data.price_reasons.length?data.technical?.close:null" :entry="!historical?data.plan?.entry:null" :stop="!historical?data.plan?.stop:null"/>
      <section class="scenario-section"><h2>三种走势预案</h2><div><article v-for="scenario in data.scenarios" :key="scenario.name" class="panel"><h3>{{scenario.name}}</h3><p>{{scenario.condition}}</p><p class="subtle">{{scenario.action}}</p></article></div></section>
      <section class="panel decision-evidence"><h2>观点证据与方案记录</h2><p class="subtle">有效样本 {{data.sample.effective_posts}} 条 · 独立作者 {{data.sample.authors}} 位 · 看多 {{data.sample.counts.bullish}} / 看空 {{data.sample.counts.bearish}} / 未识别 {{data.sample.counts.neutral}}</p><article v-for="e in data.evidence" :key="e.source_id"><p>{{e.excerpt}}</p><a :href="e.url" target="_blank" rel="noopener noreferrer">原帖证据</a></article><details><summary>已保存方案（{{records.length}}）</summary><button v-for="entry in records" :key="entry.id" class="saved-decision" @click="openRecord(entry)">#{{entry.id}} · {{time(entry.created_at)}} · {{entry.result.status}}</button><p v-if="!records.length" class="subtle">点击“更新数据并生成方案”后留存研究记录。</p></details></section>
      <details class="panel decision-method"><summary>状态与计算口径</summary><div class="state-definitions"><p v-for="[state,explanation] in states" :key="state"><strong>{{state}}</strong> · {{explanation}}</p></div><p>{{data.method}}</p><ul><li v-for="line in data.limitations" :key="line">{{line}}</li></ul><p>已保存方案用于后续验证；当前尚无成熟策略样本，不展示胜率、盈亏比或最大回撤。</p></details>
    </template>
    <p v-else-if="!error" class="decision-empty" role="status">正在核验已保存数据…</p>
  </div>
</template>
<style scoped>.decision-center{display:grid;gap:24px}.decision-search{padding:28px}.decision-heading{display:flex;justify-content:space-between;gap:20px}.decision-heading p{margin-top:10px}.decision-selector{display:flex;gap:22px;align-items:center;flex-wrap:wrap}.decision-selector>strong{margin-right:auto;font-size:19px}.decision-selector small{color:var(--muted);font-size:12px;display:inline-block;margin-left:10px;font-weight:400}.decision-selector label{display:flex;align-items:center;gap:12px;font-size:12px}.decision-summary{display:grid;grid-template-columns:1fr 1fr 1fr;gap:30px;padding:30px}.decision-summary>div+div{border-left:1px solid var(--border);padding-left:30px}.decision-summary span{color:var(--muted);font-size:13px}.decision-summary strong{display:block;font-size:40px;margin:12px 0}.decision-summary small{font-size:14px;color:var(--muted)}.decision-summary h2{font-size:29px;color:var(--accent);margin:16px 0}.decision-asof p{margin:16px 0;font-size:16px}.decision-asof small{font-size:12px}.decision-gates h2{color:var(--bull)}.decision-gates ul{color:var(--muted);font-size:13px;line-height:2;padding-left:18px}.decision-dimensions{display:grid;grid-template-columns:repeat(3,1fr);gap:24px;margin-top:24px}.decision-dimensions article{border-top:1px solid var(--border);padding-top:18px}.decision-dimensions header{display:flex;justify-content:space-between;gap:14px}.decision-dimensions h3{font-size:14px}.decision-dimensions header span{color:var(--muted);font-size:12px}.decision-dimensions strong{display:block;font-size:22px;margin:16px 0}.dimension-track{height:4px;background:var(--surface-alt);margin-bottom:14px}.dimension-track i{display:block;height:100%;background:var(--accent)}.decision-dimensions p{color:var(--muted);font-size:12px;line-height:1.9}.technical-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:24px;margin:24px 0}.technical-grid span,.plan-grid span{font-size:12px;color:var(--muted)}.technical-grid strong,.plan-grid strong{display:block;font-size:23px;margin-top:10px}.decision-empty{padding:24px 0;color:var(--muted);font-size:13px;line-height:1.9}.decision-risk{color:var(--bull);font-size:13px;margin:16px 0}.plan-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:24px;margin:24px 0}.conditional-plan>p{margin-top:16px;font-size:13px}.scenario-section>div{display:grid;grid-template-columns:repeat(3,1fr);gap:24px;margin-top:20px}.scenario-section article p{font-size:13px;line-height:1.9;margin-top:14px}.decision-evidence>p{margin-top:12px}.decision-evidence article{border-top:1px solid var(--border);margin-top:18px;padding-top:16px;font-size:13px}.decision-evidence a{display:inline-block;margin-top:10px;color:var(--accent);font-size:12px}.decision-evidence details{margin-top:22px}.decision-evidence summary,.decision-method summary{cursor:pointer}.saved-decision{display:block;padding:14px 0;color:var(--accent);font-size:12px;text-align:left}.decision-method{color:var(--muted);font-size:12px;line-height:1.9}.state-definitions{margin:16px 0}.decision-notice{padding:16px 18px;border-left:3px solid var(--accent);color:var(--muted);font-size:13px;background:var(--surface-alt)}.technical-reference .panel-heading,.conditional-plan .panel-heading{flex-wrap:wrap}
@media(max-width:900px){.decision-dimensions{grid-template-columns:1fr 1fr}.decision-summary{grid-template-columns:1fr 1fr}.decision-summary .decision-asof{grid-column:1/-1;padding-left:0;border-left:0;border-top:1px solid var(--border);padding-top:20px}.scenario-section>div{grid-template-columns:1fr}.technical-grid{grid-template-columns:repeat(3,1fr)}}@media(max-width:550px){.decision-search{padding:22px 18px}.decision-heading{flex-wrap:wrap;gap:8px}.decision-heading h1{font-size:25px}.decision-selector{gap:18px}.decision-selector>.primary{width:100%}.decision-summary{padding:22px 18px;gap:20px}.decision-summary>div+div{padding-left:20px}.decision-summary h2{font-size:24px}.decision-dimensions{gap:20px}.technical-grid{grid-template-columns:1fr 1fr}.technical-grid strong,.plan-grid strong{font-size:20px}.plan-grid{grid-template-columns:1fr}.decision-summary .decision-asof{padding-left:0}}
</style>
